import type { ReactNode, ReactElement, CSSProperties, ButtonHTMLAttributes, InputHTMLAttributes, KeyboardEvent } from 'react';

export type IconName = string;
export type Presence = 'online' | 'idle' | 'offline';

export interface IconProps { name: IconName; size?: number; strokeWidth?: number; label?: string; className?: string }
export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> { variant?: 'primary' | 'secondary' | 'ghost' | 'danger'; size?: 'sm' | 'md' | 'lg'; block?: boolean; icon?: IconName; iconRight?: IconName; children?: ReactNode }
export interface IconButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> { icon: IconName; label: string; size?: number; iconSize?: number; pressed?: boolean }
export interface TextFieldProps extends InputHTMLAttributes<HTMLInputElement> { label?: string; hint?: string; error?: string; multiline?: boolean; rows?: number; labelAside?: ReactNode; action?: ReactNode; /** Formatting bar between the label and the field. */ toolbar?: ReactNode; /** Receives the input element. */ inputRef?: { current: HTMLInputElement | HTMLTextAreaElement | null } }
export interface ToolbarProps { label: string; /** Id of the field the bar edits. */ controls?: string; className?: string; children: ReactNode }
export interface SwitchProps extends InputHTMLAttributes<HTMLInputElement> { label?: string }
export interface CheckboxProps extends InputHTMLAttributes<HTMLInputElement> { label?: ReactNode; ariaLabel?: string }
export interface SegmentedControlProps { options: Array<string | { value: string; label: ReactNode }>; value: string; onChange?: (value: string) => void; label: string; block?: boolean }
export interface BadgeProps { tone?: 'neutral' | 'accent'; icon?: IconName; /** Without children, names the icon-only badge for screen readers and on hover. */ label?: string; children?: ReactNode }
export interface CountBadgeProps { count: number; mention?: boolean }
export interface AvatarProps { name: string; size?: number; status?: Presence; color?: string; ring?: string; square?: boolean; /** Profile picture. The initials stay visible if it does not load. */ src?: string | null; /** Called when the profile picture has loaded. */ onLoad?: () => void }
export interface NavItemProps { label: ReactNode; icon?: IconName; avatar?: ReactNode; active?: boolean; unread?: boolean; count?: number; mention?: boolean; muted?: boolean; href?: string; onClick?: () => void; trailing?: ReactNode }
export interface MessageProps { time: string; /** A text becomes a p.tc-msg-text with its @mentions, an element renders as is. */ children: ReactNode; /** A text becomes a span.tc-msg-author, an element renders as is. */ author?: ReactNode; avatar?: ReactNode; /** Role and channel after the name. */ meta?: ReactNode; reply?: { author?: ReactNode; avatar?: ReactNode; text: ReactNode; /** Turns the quoted text into a button that goes to the original message. */ onJump?: () => void } | null; /** Content of the hover action bar. */ actions?: ReactNode; /** Drawn behind the whole row and under the text, such as a member's message background image. Hidden by highlight. */ background?: ReactNode; compact?: boolean; continued?: boolean; mention?: boolean; /** Set as data-msg-id to find the row in the message log. */ msgId?: string; /** selected background, in front of the member background. */ highlight?: boolean; className?: string; style?: CSSProperties }
export interface DayDividerProps { children: ReactNode; /** Day of the divider: shows the moon of that night. */ date?: number | Date }
export interface MoonProps { /** Moment whose phase is drawn, now by default. */ date?: number | Date; /** Fixed phase from 0 (new moon) to 1, takes precedence over date. */ phase?: number; size?: number; /** true: phase name and lit part. Text: the given label. Absent: decorative. */ label?: boolean | string; className?: string; style?: CSSProperties }
export interface MoonPhase { phase: number; lit: number; name: string }
export interface BannerProps { tone?: 'info' | 'warning'; /** An icon name, or a 16px element that replaces the icon (a state that animates, for example). */ icon?: IconName | ReactElement; title?: ReactNode; children: ReactNode; action?: ReactNode; onDismiss?: () => void }
export interface SettingsSectionProps { title?: ReactNode; description?: ReactNode; headerAside?: ReactNode; padded?: boolean; children?: ReactNode }
export interface SettingRowProps { title: ReactNode; description?: ReactNode; control: ReactNode; badge?: ReactNode; asLabel?: boolean }
export interface SaveBarProps { children: ReactNode; onDiscard?: () => void; onSave?: () => void; saveLabel?: string; discardLabel?: string }
export interface ComposerProps { placeholder: string; onSend: (text: string) => void; value?: string; onChange?: (value: string) => void; /** Message the send relates to, shown above the field (reply, edit, quote). */ context?: { icon: IconName; verb: string; author: string; text: string; cancelLabel: string; /** Full-width line under the context, with the info icon. */ note?: string } | null; onCancelContext?: () => void; /** Send in progress, shown with a spinner above the field ("Uploading cat.png"). */ status?: string | null; /** File that leaves with the next send, shown above the field. While set, Send works with an empty field. Without onRemove, no remove button. */ attachment?: { name: string; preview?: string | null; icon?: IconName; note?: string | null; onRemove?: (() => void) | null } | null; /** Called before the composer handles the key, which it ignores if the handler calls preventDefault. */ onKeyDown?: (e: KeyboardEvent<HTMLTextAreaElement>) => void; onTyping?: () => void; onEmoji?: () => void; onAttach?: () => void; aside?: ReactNode; beforeSend?: ReactNode; label?: string; /** Short text in the bar, such as a character count, that also describes the field. */ hint?: ReactNode; /** warning adds the alert icon, for a text that blocks sending. */ hintTone?: 'neutral' | 'warning'; /** When false, Send is disabled and Enter neither sends nor clears the field. */ canSend?: boolean; /** Receives the input element, to give it focus back. */ inputRef?: { current: HTMLTextAreaElement | null } }
export interface SkeletonProps { width: number | string; height?: number | string; circle?: boolean }
export interface SpinnerProps { size?: number; /** Accessible name, left out when a visible text already announces the loading. */ label?: string }
